/*
 * A285467  1-limiting word of the morphism 0->11, 1-> 0001.
 * https://oeis.org/A285467
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = n-th term of the 1‑limiting word of the morphism 0 → 11,
 *            1 → 0001. The word is generated by iterating the rule g0 = f²(0)
 *            = 00010001 and g1 = f²(1) = 1111110001
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>

seq_t a(idx_t n)
{
    static seq_t *buf = NULL;   /* current prefix of the infinite word */
    static idx_t len = 0;       /* current length of buf */

    /* initialise with the first odd‑iteration word (11) if needed */
    if (len == 0) {
        buf = (seq_t *)malloc(2 * sizeof(seq_t));
        buf[0] = 1;
        buf[1] = 1;
        len = 2;
    }

    /* grow the word until it contains at least n symbols */
    while (len < n) {
        idx_t zeros = 0, ones = 0;
        for (idx_t i = 0; i < len; ++i) {
            if (buf[i] == 0)
                ++zeros;
            else
                ++ones;
        }

        idx_t new_len = zeros * 8 + ones * 10;
        seq_t *new_buf = (seq_t *)malloc(new_len * sizeof(seq_t));
        seq_t *p = new_buf;

        static const seq_t g0[8]  = {0,0,0,1,0,0,0,1};
        static const seq_t g1[10] = {1,1,1,1,1,1,0,0,0,1};

        for (idx_t i = 0; i < len; ++i) {
            if (buf[i] == 0) {
                for (idx_t j = 0; j < 8; ++j)
                    *p++ = g0[j];
            } else {
                for (idx_t j = 0; j < 10; ++j)
                    *p++ = g1[j];
            }
        }

        free(buf);
        buf = new_buf;
        len = new_len;
    }

    return buf[n - 1];   /* sequence indices start at 1 */
}
